下面是系统真实可用的工具Schema：

[
  {
    "name": "search_codebase",
    "description": "根据自然语言问题、函数名、类名或变量名，在代码仓库中检索相关代码。当需要寻找代码位置或理解功能实现时使用。",
    "parameters": {
      "type": "object",
      "properties": {
        "query": {
          "type": "string",
          "description": "要检索的问题、函数名、类名或代码关键词"
        },
        "top_k": {
          "type": "integer",
          "description": "返回多少个相关代码块",
          "minimum": 1,
          "maximum": 10,
          "default": 5
        }
      },
      "required": [
        "query"
      ],
      "additionalProperties": false
    }
  },
  {
    "name": "analyze_code",
    "description": "使用 AST 分析一个 Python 文件，返回类、函数、导入、圈复杂度和潜在问题。",
    "parameters": {
      "type": "object",
      "properties": {
        "relative_path": {
          "type": "string",
          "description": "相对于仓库根目录的 Python 文件路径，例如 model.py"
        }
      },
      "required": [
        "relative_path"
      ],
      "additionalProperties": false
    }
  },
  {
    "name": "analyze_log",
    "description": "分析 Python traceback 或错误日志，提取异常类型、报错文件和行号，并读取仓库内相关代码上下文。",
    "parameters": {
      "type": "object",
      "properties": {
        "log_text": {
          "type": "string",
          "description": "用户提供的完整Traceback、错误日志或单行异常片段"
        },
        "context_lines": {
          "type": "integer",
          "description": "报错行前后读取多少行代码",
          "minimum": 1,
          "maximum": 30,
          "default": 8
        }
      },
      "required": [
        "log_text"
      ],
      "additionalProperties": false
    }
  },
  {
    "name": "complete_code",
    "description": "读取指定代码区域，并根据用户要求准备代码修改或补全所需的上下文。",
    "parameters": {
      "type": "object",
      "properties": {
        "relative_path": {
          "type": "string",
          "description": "需要修改的仓库内文件路径"
        },
        "instruction": {
          "type": "string",
          "description": "具体修改或补全要求"
        },
        "start_line": {
          "type": "integer",
          "description": "起始行号",
          "minimum": 1,
          "default": 1
        },
        "end_line": {
          "type": "integer",
          "description": "结束行号",
          "minimum": 1
        }
      },
      "required": [
        "relative_path",
        "instruction"
      ],
      "additionalProperties": false
    }
  },
  {
    "name": "generate_tests",
    "description": "读取 Python 文件及其结构信息，为指定函数、方法或类准备 pytest 测试生成任务。",
    "parameters": {
      "type": "object",
      "properties": {
        "relative_path": {
          "type": "string",
          "description": "需要生成测试的 Python 文件"
        },
        "target_name": {
          "type": "string",
          "description": "需要测试的函数、方法或类名称；省略时分析整个文件"
        }
      },
      "required": [
        "relative_path"
      ],
      "additionalProperties": false
    }
  },
  {
    "name": "generate_dockerfile",
    "description": "扫描仓库结构、依赖文件和程序入口，准备生成 Dockerfile 所需的信息。",
    "parameters": {
      "type": "object",
      "properties": {
        "entrypoint": {
          "type": "string",
          "description": "程序入口，例如 main.py 或 app.py；不确定时可以省略"
        },
        "python_version": {
          "type": "string",
          "description": "目标 Python 版本，例如 3.11",
          "default": "3.11"
        }
      },
      "required": [],
      "additionalProperties": false
    }
  }
]

